#!/usr/bin/env node
// Export the contract ABI for the static frontend.
// Reads build/FlameID.json and writes frontend/abi.js
// (a plain `const CONTRACT_ABI = [...]` the browser can load).
// Run after every recompile: node scripts/export_frontend_abi.js
const fs = require("fs");
const path = require("path");

const ROOT = path.join(__dirname, "..");
const artifact = JSON.parse(
  fs.readFileSync(path.join(ROOT, "build", "FlameID.json"), "utf8")
);
const out =
  "// Auto-generated by scripts/export_frontend_abi.js — do not edit by hand.\n" +
  `// Contract: ${artifact.contractName} (solc ${artifact.compilerVersion})\n` +
  `const CONTRACT_ABI = ${JSON.stringify(artifact.abi, null, 2)};\n`;
fs.writeFileSync(path.join(ROOT, "frontend", "abi.js"), out);
console.log(`wrote frontend/abi.js (${artifact.abi.length} ABI entries)`);
